Lemma wbytes_eq : forall bs m a, wbytes m a bs = write_to_mem m a bs.
Proof. induction bs as [|b bs IH]; intros m a; cbn; [reflexivity | apply IH]. Qed.

Lemma wa_eq : forall z, wa z = Z_to_bv 64 z. Proof. reflexivity. Qed.

