Lemma find_segment_rsegs : forall (x : Z),
  find_segment usegs x 1 =
    if ((0x10000 <=? x) && (x + 1 <=? 0x2b000))%Z then Some Ubsan.Ubsan_segment_000
    else if ((0x2b000 <=? x) && (x + 1 <=? 0x7e000))%Z then Some Ubsan.Ubsan_segment_001
    else if ((0x7e000 <=? x) && (x + 1 <=? 0x84000))%Z then Some Ubsan.Ubsan_segment_002
    else if ((0x84000 <=? x) && (x + 1 <=? 0xb8000))%Z then Some Ubsan.Ubsan_segment_003
    else None.
Proof. intros x. reflexivity. Qed.

Lemma ro_addr_true : forall (a : word), 0x10000 <= bv_unsigned a < 0x7e000 -> ro_addr usegs a = true.
Proof.
  intros a Ha. unfold ro_addr. rewrite find_segment_rsegs.
  destruct (Z.leb_spec 0x10000 (bv_unsigned a)); destruct (Z.leb_spec (bv_unsigned a + 1) 0x2b000); cbn [andb]; [reflexivity| | lia | lia].
  destruct (Z.leb_spec 0x2b000 (bv_unsigned a)); destruct (Z.leb_spec (bv_unsigned a + 1) 0x7e000); cbn [andb]; [reflexivity| lia | lia | lia].
Qed.

