Lemma rdn_S : forall m (a : word) n bs,
  rdn RSEGS m a (S n) = Some bs ->
  exists b r, bs = b :: r /\ mrd usegs m a = Some b /\ rdn RSEGS m (a + 1)%bv n = Some r.
Proof.
  intros m a n bs H. change (rdn RSEGS) with (OSSVerify.Proofs.boost_beast.http_request.lib.Lib.PropExec.rdn usegs) in H |- *.
  rewrite rdn_unfold in H. destruct (mrd usegs m a) as [b|]; [|discriminate].
  destruct (OSSVerify.Proofs.boost_beast.http_request.lib.Lib.PropExec.rdn usegs m (a + 1)%bv n) as [r|]; [|discriminate].
  injection H as <-. exists b, r. auto.
Qed.
